package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

const MD = 998244353

var ff, gg []int

func power(a int, k int) int64 {
	if k == 0 {
		return 1
	}
	p := power(a, k>>1)
	p = p * p % MD
	if k&1 == 1 {
		p = p * int64(a) % MD
	}
	return p
}

func ch(n, k int) int64 {
	return int64(ff[n]) * int64(gg[k]) % MD * int64(gg[n-k]) % MD
}

var reader *bufio.Reader
var writer *bufio.Writer

func readInt() int {
	n, _ := strconv.ParseInt(readToken(), 10, 64)
	return int(n)
}

func readLong() int64 {
	n, _ := strconv.ParseInt(readToken(), 10, 64)
	return n
}

func readToken() string {
	buf := make([]byte, 0, 16)
	for {
		b, err := reader.ReadByte()
		if err != nil {
			break
		}
		if b == ' ' || b == '\n' || b == '\r' || b == '\t' {
			if len(buf) > 0 {
				break
			}
			continue
		}
		buf = append(buf, b)
	}
	return string(buf)
}

func main() {
	reader = bufio.NewReader(os.Stdin)
	writer = bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	n := readInt()
	k_ := readLong()
	if k_ >= int64(n) {
		fmt.Fprintln(writer, 0)
		return
	}
	c := n - int(k_)
	ff = make([]int, n+n)
	gg = make([]int, n+n)
	f := 1
	for i := 0; i < n+n; i++ {
		ff[i] = f
		gg[i] = int(power(ff[i], MD-2))
		f = int(int64(f) * int64(i+1) % MD)
	}
	var ans int64 = 0
	for a := 1; a <= c; a++ {
		x := power(a, n) * ch(c, a) % MD
		if (c-a)%2 == 0 {
			ans += x
		} else {
			ans -= x
		}
	}
	ans %= MD
	if ans < 0 {
		ans += MD
	}
	ans = ans * ch(n, c) % MD
	if k_ > 0 {
		ans = ans * 2 % MD
	}
	fmt.Fprintln(writer, ans)
}
